//! The National Pokédex: all 1025 Pokémon, generated from PokeAPI's data
//! (`pokemon_species.csv`, `pokemon_types.csv`, `pokemon_species_names.csv`).
//! `name` is the sprite and cry file name; `t1`/`t2` index `pokemon::TYPES` (255 = none);
//! `stage` is 0 for a first stage, 1 and 2 for its evolutions; `legend` covers legendaries,
//! mythicals, Ultra Beasts and Paradox Pokémon.

pub struct Species {
    pub id: u16,
    pub name: &'static str,
    pub display: &'static str,
    pub t1: u8,
    pub t2: u8,
    pub stage: u8,
    pub baby: bool,
    pub legend: bool,
    pub generation: u8,
    /// 0 for a National Pokédex entry; otherwise an index into `FORM_KINDS`.
    pub form: u8,
    /// The National Pokédex number of the species (its own for a National entry).
    pub base: u16,
}

/// The kinds of form, by `Species::form` (Alolan… forms, Mega Evolutions and Primal
/// Reversions, Gigantamax forms).
pub const FORM_KINDS: [&str; 7] = ["", "Alola", "Galar", "Hisui", "Paldea", "Mega", "Gigantamax"];

/// The regions, by generation.
pub const REGIONS: [&str; 9] = ["Kanto", "Johto", "Hoenn", "Sinnoh", "Unova", "Kalos", "Alola", "Galar", "Paldea"];

/// Evolutions: (from id, to id, the team level it happens at). Level-up evolutions use the
/// game's level; friendship 20, stones 30, trades 36, anything else 30; always at least 5
/// levels after the evolution before.
